// ===============================
// CandidateIQ - Calculate Available Interview Slots
// ===============================

// ===== Configuration =====
const CONFIG = {
    workStartHour: 9,
    workEndHour: 17,
    slotDurationMinutes: 60,
    workingDays: [1, 2, 3, 4, 5], // Monday-Friday
};

// ===== Input =====
const input = $input.first().json;

const calendarKey = Object.keys(input.calendars)[0];
const busySlots = input.calendars[calendarKey].busy || [];

const searchStart = new Date(input.timeMin);
const searchEnd = new Date(input.timeMax);

// Convert busy slots to Date objects
const busy = busySlots.map(slot => ({
    start: new Date(slot.start),
    end: new Date(slot.end),
}));

const availableSlots = [];

// ===== Helper =====
function createSlot(start, end) {
    return {
        start: start.toISOString(),
        end: end.toISOString(),
        display: `${start.toLocaleDateString('en-IE', {
            weekday: 'short',
            day: '2-digit',
            month: 'short',
            year: 'numeric',
        })} | ${start.toLocaleTimeString('en-IE', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: false,
        })} - ${end.toLocaleTimeString('en-IE', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: false,
        })}`,
    };
}

// ===== Loop through each day =====
for (
    let day = new Date(searchStart);
    day <= searchEnd;
    day.setDate(day.getDate() + 1)
) {
    const currentDay = new Date(day);

    // Skip weekends
    if (!CONFIG.workingDays.includes(currentDay.getDay())) {
        continue;
    }

    // Working hours
    let workStart = new Date(currentDay);
    workStart.setHours(CONFIG.workStartHour, 0, 0, 0);

    let workEnd = new Date(currentDay);
    workEnd.setHours(CONFIG.workEndHour, 0, 0, 0);

    // Respect searchStart on first day
    if (
        workStart.toDateString() === searchStart.toDateString() &&
        searchStart > workStart
    ) {
        workStart = new Date(searchStart);
    }

    // Respect searchEnd on last day
    if (
        workEnd.toDateString() === searchEnd.toDateString() &&
        searchEnd < workEnd
    ) {
        workEnd = new Date(searchEnd);
    }

    // Busy slots for current day
    const todaysBusy = busy
        .filter(slot => slot.start.toDateString() === currentDay.toDateString())
        .sort((a, b) => a.start - b.start);

    let currentPointer = new Date(workStart);

    for (const meeting of todaysBusy) {

        // Generate free slots before meeting
        while (
            currentPointer.getTime() + CONFIG.slotDurationMinutes * 60000 <=
            meeting.start.getTime()
        ) {
            const slotEnd = new Date(
                currentPointer.getTime() +
                CONFIG.slotDurationMinutes * 60000
            );

            availableSlots.push(createSlot(currentPointer, slotEnd));

            currentPointer = slotEnd;
        }

        // Move pointer after meeting
        if (meeting.end > currentPointer) {
            currentPointer = new Date(meeting.end);
        }
    }

    // Remaining free time after last meeting
    while (
        currentPointer.getTime() + CONFIG.slotDurationMinutes * 60000 <=
        workEnd.getTime()
    ) {
        const slotEnd = new Date(
            currentPointer.getTime() +
            CONFIG.slotDurationMinutes * 60000
        );

        availableSlots.push(createSlot(currentPointer, slotEnd));

        currentPointer = slotEnd;
    }
}

// ===== Output =====
return [
    {
        json: {
            interviewer: calendarKey,
            total_slots: availableSlots.length,
            first_available_slot: availableSlots[0] ?? null,
            available_slots: availableSlots,
        },
    },
];
